import 'package:flutter/material.dart';
import '../theme/app_theme.dart';

class ChatInputBar extends StatefulWidget {
  final TextEditingController controller;
    final ValueChanged<String> onSend;
      final bool isBusy;

        const ChatInputBar({
            super.key,
                required this.controller,
                    required this.onSend,
                        this.isBusy = false,
                          });

                            @override
                              State<ChatInputBar> createState() => _ChatInputBarState();
                              }

                              class _ChatInputBarState extends State<ChatInputBar> {
                                bool _hasText = false;

                                  @override
                                    void initState() {
                                        super.initState();
                                            widget.controller.addListener(_onChanged);
                                              }

                                                void _onChanged() {
                                                    final has = widget.controller.text.trim().isNotEmpty;
                                                        if (has != _hasText) setState(() => _hasText = has);
                                                          }

                                                            @override
                                                              void dispose() {
                                                                  widget.controller.removeListener(_onChanged);
                                                                      super.dispose();
                                                                        }

                                                                          void _handleSend() {
                                                                              if (!_hasText || widget.isBusy) return;
                                                                                  widget.onSend(widget.controller.text.trim());
                                                                                    }

                                                                                      @override
                                                                                        Widget build(BuildContext context) {
                                                                                            final isDark = Theme.of(context).brightness == Brightness.dark;
                                                                                                final surface = isDark ? AppTheme.surfaceDark : AppTheme.surfaceLight;
                                                                                                    final muted = isDark ? AppTheme.mutedDark : AppTheme.mutedLight;

                                                                                                        return SafeArea(
                                                                                                              top: false,
                                                                                                                    child: Container(
                                                                                                                            margin: const EdgeInsets.fromLTRB(12, 6, 12, 12),
                                                                                                                                    padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                                                                                                                                            decoration: BoxDecoration(
                                                                                                                                                      color: surface,
                                                                                                                                                                borderRadius: BorderRadius.circular(28),
                                                                                                                                                                          border: Border.all(
                                                                                                                                                                                      color: isDark
                                                                                                                                                                                                      ? Colors.white.withOpacity(0.06)
                                                                                                                                                                                                                      : Colors.black.withOpacity(0.05),
                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                          boxShadow: [
                                                                                                                                                                                                                                                      BoxShadow(
                                                                                                                                                                                                                                                                    color: Colors.black.withOpacity(isDark ? 0.3 : 0.06),
                                                                                                                                                                                                                                                                                  blurRadius: 24,
                                                                                                                                                                                                                                                                                                offset: const Offset(0, 6),
                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                      ],
                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                      child: Row(
                                                                                                                                                                                                                                                                                                                                                crossAxisAlignment: CrossAxisAlignment.end,
                                                                                                                                                                                                                                                                                                                                                          children: [
                                                                                                                                                                                                                                                                                                                                                                      IconButton(
                                                                                                                                                                                                                                                                                                                                                                                    icon: Icon(Icons.add_rounded, color: muted),
                                                                                                                                                                                                                                                                                                                                                                                                  onPressed: () {},
                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                          Expanded(
                                                                                                                                                                                                                                                                                                                                                                                                                                        child: ConstrainedBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                        constraints: const BoxConstraints(maxHeight: 120),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          controller: widget.controller,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            minLines: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              maxLines: 5,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                textInputAction: TextInputAction.newline,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style: TextStyle(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fontSize: 15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: isDark ? AppTheme.textDark : AppTheme.textLight,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              decoration: InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  hintText: 'Tanya apa saja...',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      hintStyle: TextStyle(color: muted, fontSize: 15),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: InputBorder.none,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              isDense: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  contentPadding:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const EdgeInsets.symmetric(vertical: 12, horizontal: 4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(width: 4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              AnimatedContainer(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            duration: const Duration(milliseconds: 200),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin: const EdgeInsets.all(4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: _hasText && !widget.isBusy
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? AppTheme.primary
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : Colors.transparent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shape: BoxShape.circle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: IconButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            icon: Icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              _hasText ? Icons.arrow_upward_rounded : Icons.mic_none_rounded,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: _hasText && !widget.isBusy
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ? Colors.white
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : (isDark ? AppTheme.mutedDark : AppTheme.mutedLight),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              size: 20,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onPressed: _hasText && !widget.isBusy ? _handleSend : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }